import snapshot from './books.json';
import links from './book-links.json';

export const books = snapshot;

/** One entry of the reading library. */
export type Book = (typeof snapshot)[number];

export const readingStatusLabels: Record<string, string> = { reading: 'Reading', read: 'Read', 'to-read': 'To read', abandoned: 'Abandoned', unknown: 'Not recorded' };

/** External links for a book, verified through Wikidata so both point at the same work. Generated by scripts/link-books.ts. */
export interface BookLink {
  /** Wikidata item id, such as "Q8337". */
  wikidata: string;
  /** English Wikipedia article, or null when the item has none. */
  wikipedia: string | null;
}

/** Lookup by book id. Only books with a confident match appear, so a missing key means no link. */
export const bookLinks: Record<string, BookLink> = links.links;
